"""Inspect actual bilingual execution exports generated by isolated browser checks."""
import json
import subprocess
import re
from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as ET
checks = []
for locale in ['en', 'ar']:
    path = '/tmp/narvo-execution-' + locale
    with ZipFile(path + '.xlsx') as archive:
        ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        sheet = ET.fromstring(archive.read('xl/worksheets/sheet1.xml'))
        if locale == 'ar':
            assert sheet.find('s:sheetViews/s:sheetView', ns).get('rightToLeft') in ['1', 'true']
        xml = '\n'.join(archive.read(n).decode() for n in archive.namelist() if n.endswith('.xml'))
        for value in ['Synthetic correction Company', 'P-ONE', 'P-TWO', 'PCC-', 'Verified allocation correction', 'e5000000-0000-4000-8000-000000000001']:
            assert value in xml, value
        assert re.search(r'20\d\d-\d\d-\d\d', xml)
        numeric = [c.find('s:v', ns).text for c in sheet.findall('.//s:c', ns) if c.find('s:v', ns) is not None and c.get('t') not in ['s', 'str', 'inlineStr']]
        assert numeric == ['100', '100', '0', '100', '0', '100', '200', '100', '100'], numeric
        checks.append(locale + ' Excel Company/source/correction/Projects/date/reason/operator/exact amounts and RTL')
    text = subprocess.check_output(['pdftotext', '-layout', path + '.pdf', '-']).decode()
    for value in ['Synthetic correction Company', 'PCC-', 'P-ONE', 'P-TWO', '100.00', 'Verified allocation correction']:
        assert value in text, value
    if locale == 'en':
        assert 'Posted' in text and 'already included' in text
    checks.append(locale + ' PDF traceability, monetary movement and status')
Path('/tmp/narvo-project-correction-exports.json').write_text(json.dumps({'status': 'PASS', 'checks': checks}, indent=2))
print('PASS: executed correction bilingual Excel/PDF artifacts')
